function UIFishPoolCreelItemNode:Refresh(data, cb)
    if not data then
        return
    end

    if not self._goodNodeScr then 
        self._goodNodeScr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    end
    self._data = data
    self._cb = cb
    self:FillSelf()
end

function UIFishPoolCreelItemNode:FillSelf(data, cb)
    self:RefreshSelectActive(false)
    CfUtils.RefeshGoodGo(self.GoodNode, self._data.fishId, self._data.num, 0.8, nil, function()
    end)
    SetButtonAction(self.Button, function()
        fishingComponent:DelNewPointFish(self._data.fishId)
        if self._cb then
            self._cb()
        end
    end)
    KTool.SetActive(self.ImgIconGrade, true)
    CfUtils.SetUISwitchImage(self.ImgIconGrade, FishingUtils.GetFishRareNameByRare(self._data.rating) == "S" and 2 or 1)
    CfUtils.FillText(self.TextNumber, FishingUtils.GetFishRareNameByRare(self._data.rating))

    local isNew = FishingUtils.IsFishNew(self._data.fishId)
    KTool.SetActive(self.ImgNew, isNew)

    local isCanMakeBait = FishingUtils.IsCanMakeBait(self._data.fishId)
    KTool.SetActive(self.ImgIconBait, isCanMakeBait)
end

function UIFishPoolCreelItemNode:RefreshSelectActive(isTrue)
    if self._goodNodeScr then 
        self._goodNodeScr:SetCheckState(isTrue)
    end
    KTool.SetActive(self.ImgSelectBatch, isTrue)
end


